// Deterministic rrweb -> markdown digest written alongside each recording so agents
// read a ~1KB semantic timeline instead of decoding raw event JSON (~200x smaller).
const MOUSE_SUB = { 2: "click", 3: "context-menu", 4: "dblclick", 7: "touch" };
const INTERACTIVE = new Set(["button", "a", "input", "select", "textarea", "label"]);
function walkSnapshot(node, nodes, parents, parentId) {
    if (!node || typeof node !== "object")
        return;
    const nid = node.id;
    if (typeof nid === "number") {
        nodes.set(nid, node);
        if (typeof parentId === "number")
            parents.set(nid, parentId);
    }
    for (const c of node.childNodes ?? [])
        walkSnapshot(c, nodes, parents, typeof nid === "number" ? nid : parentId);
}
// Innermost click target -> nearest interactive ancestor (an SVG path resolves to its button).
function climb(nodes, parents, nid, hops = 6) {
    let cur = nid;
    for (let i = 0; i < hops; i++) {
        const n = nodes.get(cur);
        const tag = (n?.tagName ?? "").toLowerCase();
        if (n && (INTERACTIVE.has(tag) || n.attributes?.role === "button"))
            return cur;
        const up = parents.get(cur);
        if (up === undefined)
            return nid;
        cur = up;
    }
    return nid;
}
function textOf(nodes, nid, depth) {
    const n = nodes.get(nid);
    if (!n || depth < 0)
        return "";
    if (n.textContent && n.type !== 5)
        return String(n.textContent); // 5 = comment node
    const out = [];
    for (const c of n.childNodes ?? []) {
        if (!c || typeof c !== "object")
            continue;
        if (c.textContent && c.type !== 5)
            out.push(String(c.textContent));
        else if (depth > 0 && typeof c.id === "number")
            out.push(textOf(nodes, c.id, depth - 1));
    }
    return out.filter(Boolean).join(" ");
}
function label(nodes, parents, nid) {
    const resolved = climb(nodes, parents, nid);
    const n = nodes.get(resolved);
    if (!n)
        return `#node${nid}`;
    const tag = (n.tagName ?? "text").toLowerCase();
    if (tag === "html" || tag === "body") {
        return "page background (no interactive element at that point — possibly a missed click)";
    }
    const attrs = n.attributes ?? {};
    for (const key of ["data-testid", "aria-label", "placeholder", "title"]) {
        if (attrs[key])
            return `<${tag} '${String(attrs[key]).slice(0, 60)}'>`;
    }
    const text = textOf(nodes, resolved, 3).trim();
    if (text)
        return `<${tag} '${text.slice(0, 40)}'>`;
    if (attrs.id)
        return `<${tag} #${attrs.id}>`;
    const cls = String(attrs.class ?? "").split(/\s+/)[0];
    return `<${tag}${cls ? "." + cls : ""}>`;
}
// Crash context from the dump payload: message + resolved file, code frame when present.
function errorSection(error) {
    if (!error || (!error.message && !error.stack))
        return [];
    const out = ["", "## Error", `${String(error.kind ?? "error")}: ${String(error.message ?? "")}`];
    if (error.file)
        out.push(`at ${String(error.file)}`);
    if (error.frame)
        out.push("", "```", String(error.frame).slice(0, 1200), "```");
    else if (error.stack)
        out.push("", "```", String(error.stack).split("\n").slice(0, 8).join("\n"), "```");
    return out;
}
function fmtT(ms, t0) {
    const s = (ms - t0) / 1000;
    const m = Math.floor(s / 60);
    return `${String(m).padStart(2, "0")}:${(s % 60).toFixed(1).padStart(4, "0")}`;
}
export function buildReplayDigest(report) {
    const ev = Array.isArray(report.events) ? report.events : [];
    if (ev.length === 0) {
        return [
            "# Crash report",
            `Page: ${report.url ?? "?"}`,
            report.note ? `User note: "${report.note}"` : "",
            ...errorSection(report.error),
            "",
            "## Session replay",
            report.recorder === "blocked"
                ? "(recorder script never loaded in the user's browser — most likely a content blocker; no interaction events captured. The pod setting is fine; ask the user to allow the preview site in their blocker and retry)"
                : "(recorder off — no interaction events captured; set EMERGENT_OVERLAY_RRWEB=buffer on the pod to get pre-crash timelines)",
        ].filter((l) => l !== "").join("\n");
    }
    const nodes = new Map();
    const parents = new Map();
    const lines = [];
    const clicks = [];
    let meta = {};
    const t0 = ev[0].timestamp;
    let mutRun = 0;
    let mutStart = null;
    const flushMuts = () => {
        if (mutRun) {
            lines.push([mutStart, `DOM updated (${mutRun} mutation batch${mutRun > 1 ? "es" : ""})`]);
            mutRun = 0;
            mutStart = null;
        }
    };
    for (const e of ev) {
        const d = e.data ?? {};
        if (e.type === 4)
            meta = d;
        else if (e.type === 2)
            walkSnapshot(d.node, nodes, parents);
        else if (e.type === 3) {
            if (d.source === 0) {
                for (const add of d.adds ?? [])
                    walkSnapshot(add.node, nodes, parents, add.parentId);
                mutStart = mutStart ?? e.timestamp;
                mutRun++;
            }
            else if (d.source === 2 && MOUSE_SUB[d.type]) {
                flushMuts();
                const kind = MOUSE_SUB[d.type];
                lines.push([e.timestamp, `${kind.padEnd(6)} ${label(nodes, parents, d.id)}`]);
                if (kind === "click")
                    clicks.push([e.timestamp, d.id]);
            }
            else if (d.source === 5) {
                flushMuts();
                lines.push([e.timestamp, `typed  ${label(nodes, parents, d.id)} (masked, ${String(d.text ?? "").length} chars)`]);
            }
        }
    }
    flushMuts();
    const findings = [];
    const byNode = new Map();
    for (const [ts, nid] of clicks) {
        if (!byNode.has(nid))
            byNode.set(nid, []);
        byNode.get(nid).push(ts);
    }
    for (const [nid, tss] of byNode) {
        for (let i = 0; i + 2 < tss.length; i++) {
            if (tss[i + 2] - tss[i] < 1200) {
                findings.push(`rapid clicks: 3+ on ${label(nodes, parents, nid)} within ${((tss[i + 2] - tss[i]) / 1000).toFixed(1)}s`);
                break;
            }
        }
    }
    const dur = (ev[ev.length - 1].timestamp - t0) / 1000;
    const out = [
        "# Session replay digest",
        `Page: ${report.url ?? meta.href ?? "?"}`,
        `Window: last ${Math.round(dur)}s before the report  ·  ${ev.length} raw events  ·  viewport ${meta.width ?? "?"}x${meta.height ?? "?"}`,
        `User note: "${report.note ?? ""}"`,
        "",
        "## Timeline",
    ];
    let prev = "";
    for (const [ts, txt] of lines) {
        if (txt !== prev)
            out.push(`${fmtT(ts, t0)}  ${txt}`);
        prev = txt;
    }
    out.push(...errorSection(report.error));
    if (findings.length)
        out.push("", "## Detections", ...findings.map((f) => `- ${f}`));
    out.push("", "## Reading notes for agents", "- One line per physical click (mousedown/mouseup already collapsed — repeated clicks are fast clicking, not a double-click bug).", "- Input text is masked by design; lengths are real, characters are not.", `- This digest covers ONLY the ${Math.round(dur)}s above. Anything the user did earlier aged out of the recording buffer.`, "- Raw events (rrweb format) sit in the .json next to this file if you need mutation-level detail.");
    return out.join("\n");
}
